from __future__ import annotations
from pathlib import Path
import duckdb

def build_profiles(parquet_glob: str,output_dir: str="data/processed")->dict:
    out=Path(output_dir); out.mkdir(parents=True,exist_ok=True); con=duckdb.connect(); con.execute(f"CREATE OR REPLACE VIEW facts AS SELECT * FROM read_parquet('{parquet_glob}',union_by_name=true)"); provider=out/"provider_profiles.parquet"; org=out/"organization_profiles.parquet"
    con.execute(f"""COPY (SELECT provider_id,any_value(rut_beneficiario_normalizado) rut,any_value(nombre_beneficiario) nombre,min(make_date(cast(periodo AS INT),cast(mes AS INT),1)) first_seen,max(make_date(cast(periodo AS INT),cast(mes AS INT),1)) last_seen,count(*) transactions,count(DISTINCT organization_id) organizations,count(DISTINCT coalesce(subtitulo,'')||'-'||coalesce(item,'')) budget_categories,sum(try_cast(monto_devengado AS DOUBLE)) amount_devengado,avg(try_cast(monto_devengado AS DOUBLE)) avg_amount,stddev_pop(try_cast(monto_devengado AS DOUBLE)) sd_amount,count(DISTINCT coalesce(nombre_ubicacion_geografica,'')) geographic_destinations FROM facts GROUP BY provider_id) TO '{provider.as_posix()}' (FORMAT PARQUET,COMPRESSION ZSTD)""")
    con.execute(f"""COPY (WITH p AS (SELECT organization_id,provider_id,sum(try_cast(monto_devengado AS DOUBLE)) amount FROM facts GROUP BY 1,2),totals AS (SELECT organization_id,sum(amount) total FROM p GROUP BY 1),hhi AS (SELECT p.organization_id,sum(power(p.amount/t.total,2)) hhi FROM p JOIN totals t USING(organization_id) WHERE t.total>0 GROUP BY 1) SELECT f.organization_id,any_value(f.nombre_partida) institucion,any_value(f.nombre_capitulo) servicio,any_value(f.nombre_area) area,count(*) transactions,count(DISTINCT f.provider_id) providers,sum(try_cast(f.monto_devengado AS DOUBLE)) amount_devengado,any_value(h.hhi) provider_hhi FROM facts f LEFT JOIN hhi h USING(organization_id) GROUP BY f.organization_id) TO '{org.as_posix()}' (FORMAT PARQUET,COMPRESSION ZSTD)"""); con.close(); return {"providers":str(provider),"organizations":str(org)}
